CREATE TABLE IF NOT EXISTS "venues" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Venue name.
	"name" VARCHAR(160) NOT NULL,
	-- URL segment for the venue page.
	"slug" VARCHAR(180) NOT NULL UNIQUE,
	-- Street address, printed on tickets and used for directions.
	"address_line1" VARCHAR(200) NOT NULL,
	-- City, the main discovery facet.
	"city" VARCHAR(120) NOT NULL,
	-- ISO 3166-1 alpha-2 country code.
	"country_code" CHAR(2) NOT NULL,
	-- IANA zone. Doors open at a local time, and a ticket that says 19:30 must say 19:30 regardless of where it is read.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Headline capacity across all configurations. Advisory only, since what is sellable depends on the event.
	"total_capacity" INTEGER,
	-- False retires a venue without orphaning the events it hosted.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "venues" IS 'The building. It is deliberately independent of any event, because the seat map is a property of the room and is reused by every show that plays there.';
COMMENT ON COLUMN "venues"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "venues"."name" IS 'Venue name.';
COMMENT ON COLUMN "venues"."slug" IS 'URL segment for the venue page.';
COMMENT ON COLUMN "venues"."address_line1" IS 'Street address, printed on tickets and used for directions.';
COMMENT ON COLUMN "venues"."city" IS 'City, the main discovery facet.';
COMMENT ON COLUMN "venues"."country_code" IS 'ISO 3166-1 alpha-2 country code.';
COMMENT ON COLUMN "venues"."timezone" IS 'IANA zone. Doors open at a local time, and a ticket that says 19:30 must say 19:30 regardless of where it is read.';
COMMENT ON COLUMN "venues"."total_capacity" IS 'Headline capacity across all configurations. Advisory only, since what is sellable depends on the event.';
COMMENT ON COLUMN "venues"."is_active" IS 'False retires a venue without orphaning the events it hosted.';

CREATE INDEX "idx_venues_city_country"
ON "venues" ("city", "country_code");

CREATE TABLE IF NOT EXISTS "sections" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Venue the section is part of.
	"venue_id" BIGINT NOT NULL,
	-- Short identifier as signed in the building, e.g. 112 or STALLS.
	"code" VARCHAR(24) NOT NULL,
	-- Customer-facing name, e.g. Lower Bowl 112.
	"name" VARCHAR(120) NOT NULL,
	-- reserved | general_admission | standing. Reserved sections have seat rows; the other two have a capacity number and nothing else.
	"kind" VARCHAR(24) NOT NULL DEFAULT 'reserved',
	-- Tier or floor, e.g. lower or balcony, used to group the map.
	"level" VARCHAR(24),
	-- Headcount for a general-admission or standing section. Null for reserved sections, where capacity is the count of seats.
	"capacity" INTEGER,
	-- Ordering in the picker, because alphabetical section codes almost never match how people think about a room.
	"display_order" SMALLINT NOT NULL DEFAULT 0,
	-- Wheelchair accessible section, which has its own allocation rules and cannot be sold as general stock.
	"is_accessible" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "sections" IS 'A block of the venue, and the boundary where the two inventory models meet: a reserved section is sold seat by seat, a general-admission section is sold against a number. Everything downstream branches on kind.';
COMMENT ON COLUMN "sections"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "sections"."venue_id" IS 'Venue the section is part of.';
COMMENT ON COLUMN "sections"."code" IS 'Short identifier as signed in the building, e.g. 112 or STALLS.';
COMMENT ON COLUMN "sections"."name" IS 'Customer-facing name, e.g. Lower Bowl 112.';
COMMENT ON COLUMN "sections"."kind" IS 'reserved | general_admission | standing. Reserved sections have seat rows; the other two have a capacity number and nothing else.';
COMMENT ON COLUMN "sections"."level" IS 'Tier or floor, e.g. lower or balcony, used to group the map.';
COMMENT ON COLUMN "sections"."capacity" IS 'Headcount for a general-admission or standing section. Null for reserved sections, where capacity is the count of seats.';
COMMENT ON COLUMN "sections"."display_order" IS 'Ordering in the picker, because alphabetical section codes almost never match how people think about a room.';
COMMENT ON COLUMN "sections"."is_accessible" IS 'Wheelchair accessible section, which has its own allocation rules and cannot be sold as general stock.';

CREATE UNIQUE INDEX "uq_sections_venue_code"
ON "sections" ("venue_id", "code");

CREATE TABLE IF NOT EXISTS "seats" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Section the seat sits in.
	"section_id" BIGINT NOT NULL,
	-- Row as printed, e.g. AA. A string because rows are not numbers once you reach row AA.
	"row_label" VARCHAR(8) NOT NULL,
	-- Seat as printed. Also a string, because 12A is a real seat in plenty of rooms.
	"seat_number" VARCHAR(8) NOT NULL,
	-- standard | accessible | companion | obstructed_view | house. House seats are never released to general sale.
	"seat_kind" VARCHAR(24) NOT NULL DEFAULT 'standard',
	-- Coordinate on the rendered seat map. Presentation data, kept with the seat so the picker needs one query.
	"map_x" NUMERIC(8,2),
	-- Coordinate on the rendered seat map.
	"map_y" NUMERIC(8,2),
	-- False removes a seat permanently, e.g. when a camera platform replaces it.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "seats" IS 'A physical chair in a building, with no notion of price, event or availability. Those all vary per event; the chair does not, which is why the seat map is stored once per venue and not once per show.';
COMMENT ON COLUMN "seats"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "seats"."section_id" IS 'Section the seat sits in.';
COMMENT ON COLUMN "seats"."row_label" IS 'Row as printed, e.g. AA. A string because rows are not numbers once you reach row AA.';
COMMENT ON COLUMN "seats"."seat_number" IS 'Seat as printed. Also a string, because 12A is a real seat in plenty of rooms.';
COMMENT ON COLUMN "seats"."seat_kind" IS 'standard | accessible | companion | obstructed_view | house. House seats are never released to general sale.';
COMMENT ON COLUMN "seats"."map_x" IS 'Coordinate on the rendered seat map. Presentation data, kept with the seat so the picker needs one query.';
COMMENT ON COLUMN "seats"."map_y" IS 'Coordinate on the rendered seat map.';
COMMENT ON COLUMN "seats"."is_active" IS 'False removes a seat permanently, e.g. when a camera platform replaces it.';

CREATE UNIQUE INDEX "uq_seats_section_row_number"
ON "seats" ("section_id", "row_label", "seat_number");

CREATE TABLE IF NOT EXISTS "events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Venue hosting the event.
	"venue_id" BIGINT NOT NULL,
	-- Event name as advertised.
	"title" VARCHAR(200) NOT NULL,
	-- URL segment for the event page.
	"slug" VARCHAR(220) NOT NULL UNIQUE,
	-- concert | sport | theatre | comedy | conference | festival.
	"event_type" VARCHAR(24) NOT NULL DEFAULT 'concert',
	-- When the room opens. Scans before this are rejected as not_yet_valid rather than as invalid.
	"doors_at" TIMESTAMPTZ,
	-- Advertised start.
	"starts_at" TIMESTAMPTZ NOT NULL,
	-- Expected end, used to close the scanning window.
	"ends_at" TIMESTAMPTZ,
	-- Public on-sale moment. The single most concurrent second this schema will ever see.
	"on_sale_at" TIMESTAMPTZ,
	-- When online sales stop, usually a couple of hours before doors.
	"off_sale_at" TIMESTAMPTZ,
	-- draft | announced | on_sale | sold_out | postponed | cancelled | completed.
	"status" VARCHAR(24) NOT NULL DEFAULT 'draft',
	-- ISO 4217 currency every price on this event is quoted in.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Purchase limit, the crudest but most effective anti-bot control there is.
	"max_tickets_per_order" SMALLINT NOT NULL DEFAULT 8,
	-- How long a checkout hold survives. Per event because a high-demand on-sale needs a short fuse and a slow-selling theatre run does not.
	"hold_ttl_seconds" INTEGER NOT NULL DEFAULT 600,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "events" IS 'One performance, not a run or a tour. Three nights at the same venue are three rows, because inventory, pricing and scanning are all per night and nothing about them can be shared.';
COMMENT ON COLUMN "events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "events"."venue_id" IS 'Venue hosting the event.';
COMMENT ON COLUMN "events"."title" IS 'Event name as advertised.';
COMMENT ON COLUMN "events"."slug" IS 'URL segment for the event page.';
COMMENT ON COLUMN "events"."event_type" IS 'concert | sport | theatre | comedy | conference | festival.';
COMMENT ON COLUMN "events"."doors_at" IS 'When the room opens. Scans before this are rejected as not_yet_valid rather than as invalid.';
COMMENT ON COLUMN "events"."starts_at" IS 'Advertised start.';
COMMENT ON COLUMN "events"."ends_at" IS 'Expected end, used to close the scanning window.';
COMMENT ON COLUMN "events"."on_sale_at" IS 'Public on-sale moment. The single most concurrent second this schema will ever see.';
COMMENT ON COLUMN "events"."off_sale_at" IS 'When online sales stop, usually a couple of hours before doors.';
COMMENT ON COLUMN "events"."status" IS 'draft | announced | on_sale | sold_out | postponed | cancelled | completed.';
COMMENT ON COLUMN "events"."currency_code" IS 'ISO 4217 currency every price on this event is quoted in.';
COMMENT ON COLUMN "events"."max_tickets_per_order" IS 'Purchase limit, the crudest but most effective anti-bot control there is.';
COMMENT ON COLUMN "events"."hold_ttl_seconds" IS 'How long a checkout hold survives. Per event because a high-demand on-sale needs a short fuse and a slow-selling theatre run does not.';
COMMENT ON COLUMN "events"."created_at" IS 'Creation time.';

CREATE INDEX "idx_events_venue_start"
ON "events" ("venue_id", "starts_at");
CREATE INDEX "idx_events_onsale"
ON "events" ("status", "on_sale_at");

CREATE TABLE IF NOT EXISTS "event_sections" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Event being priced.
	"event_id" BIGINT NOT NULL,
	-- Section being priced for that event.
	"section_id" BIGINT NOT NULL,
	-- Face value in minor units. The same seat is a different price at a Tuesday matinee and a Saturday final.
	"price_minor" INTEGER NOT NULL,
	-- Per-ticket fee shown separately, because it is refunded under different rules than the face value.
	"service_fee_minor" INTEGER NOT NULL DEFAULT 0,
	-- Size of the general-admission pool for this event. Null for reserved sections, where the seats themselves are the capacity.
	"ga_capacity" INTEGER,
	-- Tickets sold from the pool. Incremented in the same transaction as the order, so the pool cannot go negative under concurrency.
	"ga_sold" INTEGER NOT NULL DEFAULT 0,
	-- Quantity currently inside live checkout holds. Sellable is ga_capacity minus ga_sold minus ga_held, which is the entire general-admission double-sell defence.
	"ga_held" INTEGER NOT NULL DEFAULT 0,
	-- Per-section stop-sell, independent of remaining capacity. Sections open in waves.
	"is_on_sale" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "event_sections" IS 'Where an event meets a room: price, fees and, for general admission, the capacity pool. Reserved sections carry no counters here at all, because their availability is answered row by row in seat_inventory.';
COMMENT ON COLUMN "event_sections"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "event_sections"."event_id" IS 'Event being priced.';
COMMENT ON COLUMN "event_sections"."section_id" IS 'Section being priced for that event.';
COMMENT ON COLUMN "event_sections"."price_minor" IS 'Face value in minor units. The same seat is a different price at a Tuesday matinee and a Saturday final.';
COMMENT ON COLUMN "event_sections"."service_fee_minor" IS 'Per-ticket fee shown separately, because it is refunded under different rules than the face value.';
COMMENT ON COLUMN "event_sections"."ga_capacity" IS 'Size of the general-admission pool for this event. Null for reserved sections, where the seats themselves are the capacity.';
COMMENT ON COLUMN "event_sections"."ga_sold" IS 'Tickets sold from the pool. Incremented in the same transaction as the order, so the pool cannot go negative under concurrency.';
COMMENT ON COLUMN "event_sections"."ga_held" IS 'Quantity currently inside live checkout holds. Sellable is ga_capacity minus ga_sold minus ga_held, which is the entire general-admission double-sell defence.';
COMMENT ON COLUMN "event_sections"."is_on_sale" IS 'Per-section stop-sell, independent of remaining capacity. Sections open in waves.';

CREATE UNIQUE INDEX "uq_event_sections_event_section"
ON "event_sections" ("event_id", "section_id");

CREATE TABLE IF NOT EXISTS "seat_inventory" (
	-- Event the seat is being sold for.
	"event_id" BIGINT,
	-- Seat being sold. Composite key with event_id: exactly one inventory row per seat per event, and that primary key is what makes double-selling impossible rather than unlikely.
	"seat_id" BIGINT,
	-- available | held | sold | blocked | comp. Blocked covers production kills and obstructed seats pulled late.
	"status" VARCHAR(16) NOT NULL DEFAULT 'available',
	-- Hold currently claiming the seat, null when free or sold. Cleared when the hold converts or expires.
	"hold_id" BIGINT,
	-- Expiry copied from the hold so the sweeper and the seat picker can both work without a join. Null unless status is held.
	"held_until" TIMESTAMPTZ,
	-- Order that bought the seat. Null until the money clears.
	"order_id" BIGINT,
	-- Per-seat price override in minor units, for the front row priced above its section.
	"price_minor" INTEGER,
	-- Last state change, used to push live seat-map updates to everyone else browsing.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("event_id", "seat_id")
);

COMMENT ON TABLE "seat_inventory" IS 'One row per seat per event, created when the event goes on sale. Claiming seats is an UPDATE guarded by status = available under the composite primary key, so two people clicking the same seat at the same millisecond are serialised by the database and exactly one wins.';
COMMENT ON COLUMN "seat_inventory"."event_id" IS 'Event the seat is being sold for.';
COMMENT ON COLUMN "seat_inventory"."seat_id" IS 'Seat being sold. Composite key with event_id: exactly one inventory row per seat per event, and that primary key is what makes double-selling impossible rather than unlikely.';
COMMENT ON COLUMN "seat_inventory"."status" IS 'available | held | sold | blocked | comp. Blocked covers production kills and obstructed seats pulled late.';
COMMENT ON COLUMN "seat_inventory"."hold_id" IS 'Hold currently claiming the seat, null when free or sold. Cleared when the hold converts or expires.';
COMMENT ON COLUMN "seat_inventory"."held_until" IS 'Expiry copied from the hold so the sweeper and the seat picker can both work without a join. Null unless status is held.';
COMMENT ON COLUMN "seat_inventory"."order_id" IS 'Order that bought the seat. Null until the money clears.';
COMMENT ON COLUMN "seat_inventory"."price_minor" IS 'Per-seat price override in minor units, for the front row priced above its section.';
COMMENT ON COLUMN "seat_inventory"."updated_at" IS 'Last state change, used to push live seat-map updates to everyone else browsing.';

CREATE INDEX "idx_seat_inventory_event_status"
ON "seat_inventory" ("event_id", "status");
CREATE INDEX "idx_seat_inventory_hold_expiry"
ON "seat_inventory" ("held_until");
CREATE INDEX "idx_seat_inventory_hold"
ON "seat_inventory" ("hold_id");

CREATE TABLE IF NOT EXISTS "customers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Identity, and where tickets are delivered. A transfer to an address with no account creates one.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name for the order. Null until a guest checkout is completed.
	"full_name" VARCHAR(160),
	-- Number used for day-of-event notifications such as a gate change.
	"phone" VARCHAR(32),
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "customers" IS 'The buyer, who is often not the attendee. That split is why tickets carry their own holder fields and transfers exist at all.';
COMMENT ON COLUMN "customers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "customers"."email" IS 'Identity, and where tickets are delivered. A transfer to an address with no account creates one.';
COMMENT ON COLUMN "customers"."full_name" IS 'Name for the order. Null until a guest checkout is completed.';
COMMENT ON COLUMN "customers"."phone" IS 'Number used for day-of-event notifications such as a gate change.';
COMMENT ON COLUMN "customers"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "holds" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Event the hold applies to.
	"event_id" BIGINT NOT NULL,
	-- Section for a general-admission hold, where there are no seat rows to claim. Null for reserved holds, which claim seats in seat_inventory instead.
	"section_id" BIGINT,
	-- Tickets held. For a reserved hold this equals the number of seat_inventory rows pointing here; for general admission it is the amount added to ga_held.
	"quantity" SMALLINT NOT NULL DEFAULT 1,
	-- Anonymous checkout session. Holds are created before anyone logs in, and several holds across sections share one token to form a single cart.
	"session_token" VARCHAR(64) NOT NULL,
	-- Buyer, once known. Null for the whole browsing phase, which is exactly when the hold matters most.
	"customer_id" BIGINT,
	-- active | converted | released | expired. Rows are never deleted, because abandoned-cart rates are the sharpest demand signal an on-sale produces.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- When the hold was taken.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Hard deadline, created_at plus the event TTL. Availability queries treat a hold as gone the moment this passes, so the sweeper is a cleanup job rather than a correctness requirement.
	"expires_at" TIMESTAMPTZ NOT NULL,
	-- When it was given back, either by the sweeper or by a customer abandoning the cart.
	"released_at" TIMESTAMPTZ,
	-- Order the hold became. Null for everything that expired.
	"order_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "holds" IS 'The centrepiece: a time-boxed claim on inventory that exists only during checkout. Its TTL is what lets a seat be taken out of sale for ten minutes without any money, and what guarantees it comes back if the buyer closes the tab.';
COMMENT ON COLUMN "holds"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "holds"."event_id" IS 'Event the hold applies to.';
COMMENT ON COLUMN "holds"."section_id" IS 'Section for a general-admission hold, where there are no seat rows to claim. Null for reserved holds, which claim seats in seat_inventory instead.';
COMMENT ON COLUMN "holds"."quantity" IS 'Tickets held. For a reserved hold this equals the number of seat_inventory rows pointing here; for general admission it is the amount added to ga_held.';
COMMENT ON COLUMN "holds"."session_token" IS 'Anonymous checkout session. Holds are created before anyone logs in, and several holds across sections share one token to form a single cart.';
COMMENT ON COLUMN "holds"."customer_id" IS 'Buyer, once known. Null for the whole browsing phase, which is exactly when the hold matters most.';
COMMENT ON COLUMN "holds"."status" IS 'active | converted | released | expired. Rows are never deleted, because abandoned-cart rates are the sharpest demand signal an on-sale produces.';
COMMENT ON COLUMN "holds"."created_at" IS 'When the hold was taken.';
COMMENT ON COLUMN "holds"."expires_at" IS 'Hard deadline, created_at plus the event TTL. Availability queries treat a hold as gone the moment this passes, so the sweeper is a cleanup job rather than a correctness requirement.';
COMMENT ON COLUMN "holds"."released_at" IS 'When it was given back, either by the sweeper or by a customer abandoning the cart.';
COMMENT ON COLUMN "holds"."order_id" IS 'Order the hold became. Null for everything that expired.';

CREATE INDEX "idx_holds_expiry_sweep"
ON "holds" ("status", "expires_at");
CREATE INDEX "idx_holds_session"
ON "holds" ("session_token");
CREATE INDEX "idx_holds_event_status"
ON "holds" ("event_id", "status");

CREATE TABLE IF NOT EXISTS "orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Reference quoted in support and on the receipt.
	"order_number" VARCHAR(16) NOT NULL UNIQUE,
	-- Buyer, who is charged and who holds the tickets until they are transferred.
	"customer_id" BIGINT NOT NULL,
	-- Event bought. Orders never span events, which keeps refunds and cancellations to one event at a time.
	"event_id" BIGINT NOT NULL,
	-- pending | paid | failed | cancelled | refunded | partially_refunded.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- Face value of the tickets in minor units.
	"subtotal_minor" INTEGER NOT NULL,
	-- Service and delivery fees, kept apart because most refund policies keep them.
	"fees_minor" INTEGER NOT NULL DEFAULT 0,
	-- Taxes collected on the sale.
	"taxes_minor" INTEGER NOT NULL DEFAULT 0,
	-- Amount actually charged.
	"total_minor" INTEGER NOT NULL,
	-- ISO 4217 currency of the totals.
	"currency_code" CHAR(3) NOT NULL,
	-- Gateway charge id, unique so a replayed webhook cannot double-charge or double-issue tickets.
	"payment_reference" VARCHAR(120) UNIQUE,
	-- mobile | print_at_home | will_call | post.
	"delivery_method" VARCHAR(24) NOT NULL DEFAULT 'mobile',
	-- When checkout was submitted.
	"placed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When payment cleared. Tickets are issued from this moment, not from placed_at.
	"paid_at" TIMESTAMPTZ,
	-- Cancellation time. Kept so the released inventory can be explained later.
	"cancelled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "orders" IS 'The purchase, created when a hold converts. Everything it bought is a ticket row; the order itself carries only money, because a partial refund has to act on tickets rather than on a total.';
COMMENT ON COLUMN "orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "orders"."order_number" IS 'Reference quoted in support and on the receipt.';
COMMENT ON COLUMN "orders"."customer_id" IS 'Buyer, who is charged and who holds the tickets until they are transferred.';
COMMENT ON COLUMN "orders"."event_id" IS 'Event bought. Orders never span events, which keeps refunds and cancellations to one event at a time.';
COMMENT ON COLUMN "orders"."status" IS 'pending | paid | failed | cancelled | refunded | partially_refunded.';
COMMENT ON COLUMN "orders"."subtotal_minor" IS 'Face value of the tickets in minor units.';
COMMENT ON COLUMN "orders"."fees_minor" IS 'Service and delivery fees, kept apart because most refund policies keep them.';
COMMENT ON COLUMN "orders"."taxes_minor" IS 'Taxes collected on the sale.';
COMMENT ON COLUMN "orders"."total_minor" IS 'Amount actually charged.';
COMMENT ON COLUMN "orders"."currency_code" IS 'ISO 4217 currency of the totals.';
COMMENT ON COLUMN "orders"."payment_reference" IS 'Gateway charge id, unique so a replayed webhook cannot double-charge or double-issue tickets.';
COMMENT ON COLUMN "orders"."delivery_method" IS 'mobile | print_at_home | will_call | post.';
COMMENT ON COLUMN "orders"."placed_at" IS 'When checkout was submitted.';
COMMENT ON COLUMN "orders"."paid_at" IS 'When payment cleared. Tickets are issued from this moment, not from placed_at.';
COMMENT ON COLUMN "orders"."cancelled_at" IS 'Cancellation time. Kept so the released inventory can be explained later.';

CREATE INDEX "idx_orders_customer_time"
ON "orders" ("customer_id", "placed_at");
CREATE INDEX "idx_orders_event_status"
ON "orders" ("event_id", "status");

CREATE TABLE IF NOT EXISTS "tickets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Order that issued it.
	"order_id" BIGINT NOT NULL,
	-- Event it admits to, copied so a scanner can validate without joining orders.
	"event_id" BIGINT NOT NULL,
	-- Section it admits to, which is the whole entitlement for general admission.
	"section_id" BIGINT NOT NULL,
	-- Assigned seat. Null for general admission, where the ticket buys a place in a section and not a chair.
	"seat_id" BIGINT,
	-- Stable identifier printed on a paper or will-call ticket. Never changes, which is exactly why it is the weaker of the two credentials.
	"barcode" VARCHAR(64) NOT NULL UNIQUE,
	-- Rotating credential the mobile app renders. Reissued on transfer and refreshed periodically, so a screenshot sent to a friend stops working.
	"qr_token" UUID NOT NULL UNIQUE,
	-- Attendee name, which differs from the buyer as soon as a ticket is transferred.
	"holder_name" VARCHAR(160),
	-- Attendee address, used to deliver the ticket after a transfer.
	"holder_email" VARCHAR(320),
	-- Face value paid for this ticket, snapshotted so a price change cannot rewrite a receipt.
	"price_minor" INTEGER NOT NULL,
	-- Fees attributed to this ticket, needed to refund one ticket out of six.
	"fees_minor" INTEGER NOT NULL DEFAULT 0,
	-- ISO 4217 currency of price_minor.
	"currency_code" CHAR(3) NOT NULL,
	-- issued | transferred | admitted | void | refunded. Admitted is set by the first successful scan.
	"status" VARCHAR(24) NOT NULL DEFAULT 'issued',
	-- Issue time.
	"issued_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When it stopped being valid. Void tickets are kept so a scan at the door can say why the ticket failed.
	"voided_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "tickets" IS 'One row per admission, and the unit everything acts on: transfers, scans and refunds are all per ticket. Two credentials are deliberate — a static barcode for paper and a rotating token for phones — because they fail in different ways.';
COMMENT ON COLUMN "tickets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "tickets"."order_id" IS 'Order that issued it.';
COMMENT ON COLUMN "tickets"."event_id" IS 'Event it admits to, copied so a scanner can validate without joining orders.';
COMMENT ON COLUMN "tickets"."section_id" IS 'Section it admits to, which is the whole entitlement for general admission.';
COMMENT ON COLUMN "tickets"."seat_id" IS 'Assigned seat. Null for general admission, where the ticket buys a place in a section and not a chair.';
COMMENT ON COLUMN "tickets"."barcode" IS 'Stable identifier printed on a paper or will-call ticket. Never changes, which is exactly why it is the weaker of the two credentials.';
COMMENT ON COLUMN "tickets"."qr_token" IS 'Rotating credential the mobile app renders. Reissued on transfer and refreshed periodically, so a screenshot sent to a friend stops working.';
COMMENT ON COLUMN "tickets"."holder_name" IS 'Attendee name, which differs from the buyer as soon as a ticket is transferred.';
COMMENT ON COLUMN "tickets"."holder_email" IS 'Attendee address, used to deliver the ticket after a transfer.';
COMMENT ON COLUMN "tickets"."price_minor" IS 'Face value paid for this ticket, snapshotted so a price change cannot rewrite a receipt.';
COMMENT ON COLUMN "tickets"."fees_minor" IS 'Fees attributed to this ticket, needed to refund one ticket out of six.';
COMMENT ON COLUMN "tickets"."currency_code" IS 'ISO 4217 currency of price_minor.';
COMMENT ON COLUMN "tickets"."status" IS 'issued | transferred | admitted | void | refunded. Admitted is set by the first successful scan.';
COMMENT ON COLUMN "tickets"."issued_at" IS 'Issue time.';
COMMENT ON COLUMN "tickets"."voided_at" IS 'When it stopped being valid. Void tickets are kept so a scan at the door can say why the ticket failed.';

CREATE INDEX "idx_tickets_event_status"
ON "tickets" ("event_id", "status");
CREATE INDEX "idx_tickets_order"
ON "tickets" ("order_id");
CREATE INDEX "idx_tickets_seat"
ON "tickets" ("seat_id");

CREATE TABLE IF NOT EXISTS "ticket_transfers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Ticket being handed over.
	"ticket_id" BIGINT NOT NULL,
	-- Sender, who loses the ticket only once the transfer is accepted.
	"from_customer_id" BIGINT NOT NULL,
	-- Recipient address. An email rather than a customer id, because most recipients have no account yet.
	"to_email" VARCHAR(320) NOT NULL,
	-- Recipient account, filled in on acceptance.
	"to_customer_id" BIGINT,
	-- Single-use claim link. Unique so a forwarded link cannot be redeemed twice.
	"transfer_token" UUID NOT NULL UNIQUE,
	-- pending | accepted | declined | cancelled | expired.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- When the transfer was offered.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Claim deadline. An unclaimed transfer must return the ticket to the sender before doors, not after.
	"expires_at" TIMESTAMPTZ NOT NULL,
	-- Acceptance time, which is when the ticket QR token is rotated and the old one dies.
	"accepted_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "ticket_transfers" IS 'A pending change of holder, kept as its own row rather than an update to the ticket. The history matters: resale fraud investigations follow the chain, and a ticket that has moved four times in a week is worth a second look.';
COMMENT ON COLUMN "ticket_transfers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "ticket_transfers"."ticket_id" IS 'Ticket being handed over.';
COMMENT ON COLUMN "ticket_transfers"."from_customer_id" IS 'Sender, who loses the ticket only once the transfer is accepted.';
COMMENT ON COLUMN "ticket_transfers"."to_email" IS 'Recipient address. An email rather than a customer id, because most recipients have no account yet.';
COMMENT ON COLUMN "ticket_transfers"."to_customer_id" IS 'Recipient account, filled in on acceptance.';
COMMENT ON COLUMN "ticket_transfers"."transfer_token" IS 'Single-use claim link. Unique so a forwarded link cannot be redeemed twice.';
COMMENT ON COLUMN "ticket_transfers"."status" IS 'pending | accepted | declined | cancelled | expired.';
COMMENT ON COLUMN "ticket_transfers"."created_at" IS 'When the transfer was offered.';
COMMENT ON COLUMN "ticket_transfers"."expires_at" IS 'Claim deadline. An unclaimed transfer must return the ticket to the sender before doors, not after.';
COMMENT ON COLUMN "ticket_transfers"."accepted_at" IS 'Acceptance time, which is when the ticket QR token is rotated and the old one dies.';

CREATE INDEX "idx_transfers_ticket_status"
ON "ticket_transfers" ("ticket_id", "status");
CREATE INDEX "idx_transfers_expiry_sweep"
ON "ticket_transfers" ("status", "expires_at");

CREATE TABLE IF NOT EXISTS "scans" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Ticket presented. Null when the credential matched nothing at all, which is a scan worth keeping.
	"ticket_id" BIGINT,
	-- Event the scanner was configured for, recorded even on failure so wrong-event attempts are countable.
	"event_id" BIGINT NOT NULL,
	-- Device time of the scan. Doors are the one place where clocks drift and devices are offline.
	"scanned_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- admitted | duplicate | void | wrong_event | not_yet_valid | unknown_credential.
	"result" VARCHAR(24) NOT NULL DEFAULT 'admitted',
	-- Entrance the scan happened at, which is how crowd flow is measured.
	"gate" VARCHAR(24),
	-- Scanner identifier, used to find the one handset that was offline for an hour.
	"device_id" VARCHAR(64),
	-- Staff member operating the scanner.
	"operator" VARCHAR(120),
	-- When an offline scan reached the server. The gap between scanned_at and this is why duplicates are recorded rather than prevented.
	"synced_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "scans" IS 'Append-only, and it records refusals as well as admissions. Scanners work offline and sync late, so the second scan of a ticket is stored as a duplicate rather than silently dropped: the count of duplicates per gate is how ticket fraud is actually detected.';
COMMENT ON COLUMN "scans"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "scans"."ticket_id" IS 'Ticket presented. Null when the credential matched nothing at all, which is a scan worth keeping.';
COMMENT ON COLUMN "scans"."event_id" IS 'Event the scanner was configured for, recorded even on failure so wrong-event attempts are countable.';
COMMENT ON COLUMN "scans"."scanned_at" IS 'Device time of the scan. Doors are the one place where clocks drift and devices are offline.';
COMMENT ON COLUMN "scans"."result" IS 'admitted | duplicate | void | wrong_event | not_yet_valid | unknown_credential.';
COMMENT ON COLUMN "scans"."gate" IS 'Entrance the scan happened at, which is how crowd flow is measured.';
COMMENT ON COLUMN "scans"."device_id" IS 'Scanner identifier, used to find the one handset that was offline for an hour.';
COMMENT ON COLUMN "scans"."operator" IS 'Staff member operating the scanner.';
COMMENT ON COLUMN "scans"."synced_at" IS 'When an offline scan reached the server. The gap between scanned_at and this is why duplicates are recorded rather than prevented.';

CREATE INDEX "idx_scans_ticket_time"
ON "scans" ("ticket_id", "scanned_at");
CREATE INDEX "idx_scans_event_time"
ON "scans" ("event_id", "scanned_at");
CREATE INDEX "idx_scans_event_result"
ON "scans" ("event_id", "result");

CREATE TABLE IF NOT EXISTS "refunds" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Order the money came from.
	"order_id" BIGINT NOT NULL,
	-- Ticket refunded. Null for an order-level refund such as a cancelled event.
	"ticket_id" BIGINT,
	-- requested | event_cancelled | event_postponed | duplicate_purchase | fraud | goodwill.
	"reason" VARCHAR(24) NOT NULL DEFAULT 'requested',
	-- Amount returned in minor units, always positive. The direction is implied by the table.
	"amount_minor" INTEGER NOT NULL,
	-- Whether service fees were returned too. Almost always false except when the event is cancelled, which is the single most disputed line on any ticket refund.
	"includes_fees" BOOLEAN NOT NULL DEFAULT false,
	-- ISO 4217 currency of amount_minor.
	"currency_code" CHAR(3) NOT NULL,
	-- pending | processed | failed.
	"status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- Gateway refund id, unique for idempotency.
	"provider_reference" VARCHAR(120) UNIQUE,
	-- When the refund was raised.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "refunds" IS 'Per ticket where possible, per order where not. Refunding four of six tickets is normal, and a refund column on orders cannot express it or survive the second partial refund.';
COMMENT ON COLUMN "refunds"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "refunds"."order_id" IS 'Order the money came from.';
COMMENT ON COLUMN "refunds"."ticket_id" IS 'Ticket refunded. Null for an order-level refund such as a cancelled event.';
COMMENT ON COLUMN "refunds"."reason" IS 'requested | event_cancelled | event_postponed | duplicate_purchase | fraud | goodwill.';
COMMENT ON COLUMN "refunds"."amount_minor" IS 'Amount returned in minor units, always positive. The direction is implied by the table.';
COMMENT ON COLUMN "refunds"."includes_fees" IS 'Whether service fees were returned too. Almost always false except when the event is cancelled, which is the single most disputed line on any ticket refund.';
COMMENT ON COLUMN "refunds"."currency_code" IS 'ISO 4217 currency of amount_minor.';
COMMENT ON COLUMN "refunds"."status" IS 'pending | processed | failed.';
COMMENT ON COLUMN "refunds"."provider_reference" IS 'Gateway refund id, unique for idempotency.';
COMMENT ON COLUMN "refunds"."created_at" IS 'When the refund was raised.';

CREATE INDEX "idx_refunds_order"
ON "refunds" ("order_id");

